use crate::{xg19 as b,catalog,model::*,rules::*,generated::GeneratedKind,unit_support::*,abi112_review_play_tests::Trace};
fn setup()->(Game,String){let mut g=game();fund(&mut g,0,"BQ064",3);let id=held(&mut g,b::ID,0);(g,id)}
fn action(id:&str,mode:&str,ids:Vec<String>)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),region:Some(0),option:Some(mode.into()),selected:if mode=="generate"{None}else{Some(ids)},..Action::new("play")}}
fn hidden(g:&mut Game,seat:usize,r:usize)->String{let mut c=g.make_card("JC125",seat);c.face_down=true;let id=c.id.clone();g.regions[r].cards.push(c);id}
fn top(g:&mut Game){for _ in 0..30{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
fn count(g:&Game)->usize{g.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition==b::TOKEN).count()}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn xg19_original_closed_fields_and_canonical_modes(){assert_current_serial_catalog();let c=catalog::card(b::ID);assert_eq!(c.cost,3);assert_eq!(c.loyalty,["灰色","灰色"]);assert!(!c.supported);let t=catalog::card(b::TOKEN);assert_eq!(t.cost,0);assert!(t.loyalty.is_empty());assert!(t.rule_traits.public);assert_eq!(t.permanent_icons.influence,1);assert_eq!(t.temporary_icons.combat,1);for id in [b::ID,b::TOKEN]{let mut d=b::definition(id);d.traits.slow=true;assert!(b::validate_definition(id,&d).is_err());}let(mut g,id)=setup();reject(&mut g,0,Action{card_id:Some(id),..Action::new("asset")});}
#[test]fn xg19_generate_exactly_two_public_police_without_hidden_target(){let(mut g,id)=setup();act(&mut g,0,action(&id,"generate",vec![]));assert_eq!(g.resources(0),0);top(&mut g);assert_eq!(count(&g),2);assert!(g.regions[0].cards.iter().all(|c|!c.face_down&&!c.exhausted&&g.current_public(c,0)));restore(&mut g);}
#[test]fn xg19_zero_one_two_hidden_targets_and_both_condition(){for n in 0..=2{let(mut g,id)=setup();let targets=(0..n).map(|_|hidden(&mut g,1,0)).collect::<Vec<_>>();let extra=hidden(&mut g,0,0);act(&mut g,0,action(&id,"destroy",targets.clone()));top(&mut g);assert!(targets.iter().all(|id|g.board(id).is_none()));assert!(g.board(&extra).is_some());assert_eq!(count(&g),0);}let(mut g,id)=setup();g.players[2].society_zone.exposure=2;let h=hidden(&mut g,1,0);reject(&mut g,0,action(&id,"generate",vec![]));reject(&mut g,0,action(&id,"destroy",vec![h.clone()]));act(&mut g,0,action(&id,"both",vec![h.clone()]));g.players[2].society_zone.exposure=0;restore(&mut g);top(&mut g);assert!(g.board(&h).is_none());assert_eq!(count(&g),2);}
#[test]fn xg19_rejects_wrong_region_duplicate_faceup_excess_and_unearned_both(){let(mut g,id)=setup();let a=hidden(&mut g,1,0);let b=hidden(&mut g,1,0);let c=hidden(&mut g,1,0);let far=hidden(&mut g,1,1);let face=field(&mut g,"JC125",1);for ids in [vec![a.clone(),a.clone()],vec![a.clone(),b,c],vec![far],vec![face]]{reject(&mut g,0,action(&id,"destroy",ids));}reject(&mut g,0,action(&id,"both",vec![a]));assert_eq!(g.resources(0),3);}
#[test]fn xg19_changed_target_cancels_whole_paid_program_and_replaced_region_is_not_reused(){for mode in 0..3{let(mut g,id)=setup();g.players[2].society_zone.exposure=2;let h=hidden(&mut g,1,0);act(&mut g,0,action(&id,"both",vec![h.clone()]));match mode{0=>g.board_mut(&h).unwrap().face_down=false,1=>{let(_,c)=g.remove_board(&h).unwrap();g.regions[1].cards.push(c);},_=>g.regions[0].card=g.make_card("DQJC115",0)}restore(&mut g);top(&mut g);assert_eq!(count(&g),0);assert_eq!(g.resources(0),0);assert!(g.board(&h).is_some());}}
#[test]fn xg19_corrupt_frame_target_observation_and_actual_card_rejected(){let(mut g,id)=setup();act(&mut g,0,action(&id,"generate",vec![]));for n in 0..5{let mut x=g.clone();let i=x.stack.last_mut().unwrap();match n{0=>i.frame=None,1=>i.frame.as_mut().unwrap().steps.clear(),2=>i.frame.as_mut().unwrap().targets[0].region_instance=None,3=>if let Op::XG19Resolve{mode,..}=&mut i.frame.as_mut().unwrap().steps[0].op{*mode=2},_=>i.frame.as_mut().unwrap().source.card.definition="JC001".into()};bad(&g,&x);}restore(&mut g);}
#[test]fn xg19_police_lifecycle_zero_reveal_and_restore(){let(mut g,id)=setup();act(&mut g,0,action(&id,"generate",vec![]));top(&mut g);let id=g.regions[0].cards[0].id.clone();let birth=g.board(&id).unwrap().1.generated.clone();g.hide_in_place(&id);let id=g.regions[0].cards.iter().find(|c|c.face_down).unwrap().id.clone();g.begin_window(Window::Action(0));act(&mut g,0,Action{card_id:Some(id),..Action::new("reveal")});let mut x=g.clone();x.stack.last_mut().unwrap().frame=None;bad(&g,&x);top(&mut g);let c=g.regions[0].cards.iter().find(|c|c.generated==birth).unwrap();assert!(!c.face_down);let id=c.id.clone();g.return_hand(&id);assert_eq!(count(&g),1);assert!(!g.players[0].hand.iter().any(|c|c.definition==b::TOKEN));let id=g.regions[0].cards[0].id.clone();let host=field(&mut g,"JC125",0);let(_,c)=g.leave_board(&id).unwrap();g.seal_card_on_valid_host(c,0,&host);restore(&mut g);assert_eq!(g.sealed_cards.len(),1);g.return_hand(&host);assert!(g.sealed_cards.is_empty());restore(&mut g);}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn drain(t:&mut Trace){for _ in 0..40{if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){return;}assert!(t.room.game.pending.is_none());t.pass();}panic!()}
fn prepared(mode:&str,index:usize)->serde_json::Value{let(mut g,id)=setup();if mode=="both"{g.players[2].society_zone.exposure=2;}let h=hidden(&mut g,1,0);let h2=hidden(&mut g,0,0);let mut t=Trace::new_preserving_rng(g,format!("xg19-prepared-{mode}"),index);t.action(0,action(&id,mode,vec![h,h2]));drain(&mut t);assert_eq!(count(&t.room.game),if mode=="destroy"{0}else{2});duplicate(t.value())}
fn natural()->serde_json::Value{use crate::deck;fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="xg19-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("BQ064",3),("JC125",44)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("xg19".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}let(seed,g)=(1..4097).find_map(|seed|{let g=construct(seed);(g.players[0].hand.iter().any(|c|c.definition==b::ID)&&g.players[0].hand.iter().filter(|c|c.definition=="BQ064").count()>=2).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"xg19-natural-fifty-generate".into(),821);let mut done=false;for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&[b::ID,"BQ064"].contains(&c.definition.as_str())));t.choose(opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let gray=g.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="灰").count();let a=if gray<2{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ064")))}else if g.players[0].assets.len()<3{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC125")))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY)&&a.action.option.as_deref()==Some("generate"))};if let Some(a)=a{if a.action.kind=="play"{done=true;}t.action(0,a.action.clone());}else{t.pass();}}assert!(done);assert_eq!(count(&t.room.game),2);let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn xg19_native_natural_and_all_modes_export(){let mut g=game();let c=g.make_generated(GeneratedKind::Police,0).unwrap();let id=c.id.clone();g.regions[0].cards.push(c);g.hide_in_place(&id);let id=g.regions[0].cards[0].id.clone();let mut t=Trace::new_preserving_rng(g,"xg19-prepared-police-reveal".into(),825);t.action(0,Action{card_id:Some(id),..Action::new("reveal")});drain(&mut t);let cases=vec![natural(),prepared("destroy",822),prepared("generate",823),prepared("both",824),duplicate(t.value())];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/xg19.rs",include_bytes!("xg19.rs").as_slice()),("rust-game/src/xg19_tests.rs",include_bytes!("xg19_tests.rs").as_slice()),("rust-game/src/generated.rs",include_bytes!("generated.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("XG19_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn xg19_friendly_exposure_does_not_enable_both_and_mode_is_frozen_before_payment(){let(mut g,id)=setup();g.players[1].society_zone.exposure=2;reject(&mut g,0,action(&id,"both",vec![]));act(&mut g,0,action(&id,"generate",vec![]));g.players[2].society_zone.exposure=2;restore(&mut g);top(&mut g);assert_eq!(count(&g),2);}
